  function renderMembers(){const normalizedRole=member=>Object.prototype.hasOwnProperty.call(ROLE_LABELS,String(member?.role||''))?String(member.role):'member';const ranked=(left,right)=>Number(right.online)-Number(left.online)||String(left.displayName||'').localeCompare(String(right.displayName||''),undefined,{sensitivity:'base',numeric:true});refs.onlineCount.querySelector('b').textContent=String(state.members.filter(member=>member.online).length);refs.memberGroups.replaceChildren();Object.keys(ROLE_LABELS).sort((left,right)=>(ROLE_RANKS[right]||0)-(ROLE_RANKS[left]||0)).forEach(role=>{const members=state.members.filter(member=>normalizedRole(member)===role).sort(ranked);if(!members.length)return;const section=document.createElement('section');section.className=`member-group member-group-${role}`;const heading=document.createElement('h2');heading.textContent=`${ROLE_LABELS[role]} — ${members.length}`;const list=document.createElement('div');list.className='member-list';members.forEach(member=>{const button=document.createElement('button');button.type='button';button.className=`member-button${member.online?'':' offline'}`;button.append(avatarElement(member,member.online));const copy=document.createElement('span');const name=document.createElement('strong');name.append(roleNameElement(member));if(member.caffeine)name.append(caffeineBadge());const detail=document.createElement('small');detail.textContent=member.self?'You':member.online?'Online':'Offline';copy.append(name,detail);button.append(copy);button.addEventListener('click',()=>viewMemberProfile(member));list.append(button)});section.append(heading,list);refs.memberGroups.append(section)})}
