  function updateVoicePanel(){const channel=state.voiceChannels.find(item=>item.id===state.voiceChannelId);refs.voicePanel.hidden=!state.voiceChannelId;refs.voiceStatus.textContent=state.voicePolling?'Voice reconnecting…':'Voice connected';refs.voiceRoom.textContent=channel?.name||'';refs.voiceMute.classList.toggle('active',state.voiceMuted);refs.voiceMute.setAttribute('aria-label',state.voiceMuted?'Unmute microphone':'Mute microphone');refs.voiceMute.title=state.voiceMuted?'Unmute microphone':'Mute microphone';setVoiceButtonIcon(refs.voiceMute,state.voiceMuted?'mic-off':'mic');refs.voiceDeafen.classList.toggle('active',state.voiceDeafened);refs.voiceDeafen.setAttribute('aria-label',state.voiceDeafened?'Undeafen':'Deafen');refs.voiceDeafen.title=state.voiceDeafened?'Undeafen':'Deafen'}
  function renderVoiceChannels(){refs.voiceChannelList.replaceChildren();state.voiceChannels.forEach(channel=>{const root=document.createElement('div');root.className='voice-channel';const participants=state.voiceParticipants.filter(participant=>participant.channelId===channel.id);const button=document.createElement('button');button.type='button';button.className=`voice-channel-button${state.voiceChannelId===channel.id?' connected':''}`;button.title=channel.description||`Join ${channel.name}`;const icon=document.createElementNS('http://www.w3.org/2000/svg','svg');const use=document.createElementNS('http://www.w3.org/2000/svg','use');use.setAttribute('href','#icon-volume');icon.append(use);const name=document.createElement('strong');name.textContent=channel.name;const count=document.createElement('span');count.textContent=participants.length?String(participants.length):'';button.append(icon,name,count);button.addEventListener('click',()=>void joinVoice(channel.id));root.append(button);if(participants.length){const list=document.createElement('div');list.className='voice-participant-list';participants.forEach(participant=>{const member=voiceMember(participant);const item=document.createElement('button');item.type='button';item.className=`voice-member${participant.uid===state.me?.uid?' self':''}`;item.append(avatarElement(member,true));const label=document.createElement('span');label.append(roleNameElement(member,participant.uid===state.me?.uid?`${member.displayName} (You)`:member.displayName));item.append(label);item.addEventListener('click',event=>{event.stopPropagation();viewMemberProfile(member)});list.append(item)});root.append(list)}refs.voiceChannelList.append(root)});updateVoicePanel()}
  function closeVoicePeer(uid){const entry=state.voicePeers.get(uid);if(!entry)return;clearTimeout(entry.restartTimer);try{entry.connection.ontrack=null;entry.connection.onicecandidate=null;entry.connection.onconnectionstatechange=null;entry.connection.oniceconnectionstatechange=null;entry.connection.close()}catch{}if(entry.audio){try{entry.audio._nyxVoiceSource?.disconnect();entry.audio._nyxVoiceGain?.disconnect();entry.audio._nyxVoiceCompressor?.disconnect()}catch{}entry.audio.srcObject=null;entry.audio.remove()}state.voicePeers.delete(uid)}
