  function tuneVoiceDescription(description){const sdp=String(description?.sdp||'');const match=sdp.match(/a=rtpmap:(\d+) opus\/48000(?:\/2)?/i);if(!match)return description;const payload=match[1];const fmtp=new RegExp(`a=fmtp:${payload} ([^\\r\\n]*)`,'i');const desired={useinbandfec:'1',usedtx:'0',maxaveragebitrate:'64000',maxplaybackrate:'48000','sprop-maxcapturerate':'48000'};let tuned=sdp;if(fmtp.test(tuned)){tuned=tuned.replace(fmtp,(line,parameters)=>{const values=new Map(String(parameters).split(';').map(item=>item.trim()).filter(Boolean).map(item=>{const at=item.indexOf('=');return at<0?[item.toLowerCase(),'']:[item.slice(0,at).toLowerCase(),item.slice(at+1)]}));Object.entries(desired).forEach(([key,value])=>values.set(key,value));return `a=fmtp:${payload} ${[...values].map(([key,value])=>value?`${key}=${value}`:key).join(';')}`})}else tuned=tuned.replace(match[0],`${match[0]}\r\na=fmtp:${payload} ${Object.entries(desired).map(([key,value])=>`${key}=${value}`).join(';')}`);return {type:description.type,sdp:tuned}}
  async function prioritizeVoiceSender(sender){try{const parameters=sender.getParameters();if(!parameters.encodings?.length)return;parameters.encodings.forEach(encoding=>{encoding.maxBitrate=64000;encoding.priority='high';encoding.networkPriority='high'});await sender.setParameters(parameters)}catch{}}
  async function createVoiceOffer(uid,restart=false){const entry=state.voicePeers.get(uid);if(!entry||entry.makingOffer||!state.voiceSessionId)return;entry.makingOffer=true;try{const offer=tuneVoiceDescription(await entry.connection.createOffer(restart?{iceRestart:true}:undefined));await entry.connection.setLocalDescription(offer);await Promise.all(entry.connection.getSenders().filter(sender=>sender.track?.kind==='audio').map(prioritizeVoiceSender));await sendVoiceSignal(uid,{type:'offer',description:{type:entry.connection.localDescription.type,sdp:entry.connection.localDescription.sdp}})}catch{}finally{entry.makingOffer=false}}
  function ensureVoicePeer(participant,initiate=false){const existing=state.voicePeers.get(participant.uid);if(existing&&existing.sessionId===participant.sessionId)return existing;if(existing)closeVoicePeer(participant.uid);const connection=new RTCPeerConnection({iceServers:state.voiceIceServers,bundlePolicy:'max-bundle',rtcpMuxPolicy:'require',iceCandidatePoolSize:4});const audio=document.createElement('audio');audio.autoplay=true;audio.playsInline=true;audio.muted=state.voiceDeafened;audio.volume=1;audio.hidden=true;audio.dataset.voiceUid=participant.uid;document.body.append(audio);const entry={connection,audio,sessionId:participant.sessionId,pendingCandidates:[],makingOffer:false,restartTimer:0};state.voicePeers.set(participant.uid,entry);state.voiceStream?.getAudioTracks().forEach(track=>{track.contentHint='speech';let sender=null;try{const transceiver=connection.addTransceiver(track,{direction:'sendrecv',streams:[state.voiceStream]});sender=transceiver.sender;const capabilities=window.RTCRtpSender?.getCapabilities?.('audio');const codecs=Array.isArray(capabilities?.codecs)?capabilities.codecs:[];const opus=codecs.filter(codec=>String(codec.mimeType||'').toLowerCase()==='audio/opus');if(opus.length&&typeof transceiver.setCodecPreferences==='function')transceiver.setCodecPreferences([...opus,...codecs.filter(codec=>!opus.includes(codec))])}catch{sender=connection.addTrack(track,state.voiceStream)}if(sender)void prioritizeVoiceSender(sender)});connection.onicecandidate=event=>{if(event.candidate)void sendVoiceSignal(participant.uid,{type:'candidate',candidate:event.candidate.toJSON?event.candidate.toJSON():event.candidate})};connection.ontrack=event=>{try{if('jitterBufferTarget'in event.receiver)event.receiver.jitterBufferTarget=VOICE_JITTER_BUFFER_MS}catch{}audio.srcObject=event.streams[0]||new MediaStream([event.track]);audio.muted=state.voiceDeafened;void audio.play().catch(()=>{})};const updateConnection=()=>{const status=connection.connectionState;clearTimeout(entry.restartTimer);if((status==='failed'||status==='disconnected')&&state.me?.uid.localeCompare(participant.uid)<0)entry.restartTimer=setTimeout(()=>void createVoiceOffer(participant.uid,true),status==='failed'?500:2500);else if(status==='connected')refs.voiceStatus.textContent='Voice connected';else if(status==='closed')closeVoicePeer(participant.uid)};connection.onconnectionstatechange=updateConnection;connection.oniceconnectionstatechange=updateConnection;if(initiate)setTimeout(()=>void createVoiceOffer(participant.uid),0);return entry}
  async function handleVoiceSignal(signal){const signalId=String(signal?.id||'');if(signalId&&state.voiceSignalIds.has(signalId))return;if(signalId){state.voiceSignalIds.add(signalId);if(state.voiceSignalIds.size>500)state.voiceSignalIds.delete(state.voiceSignalIds.values().next().value)}if(signal?.toSessionId&&signal.toSessionId!==state.voiceSessionId)return;const participant=voiceMember(signal.from||state.voiceParticipants.find(item=>item.uid===signal.fromUid));if(!participant?.uid||participant.uid===state.me?.uid||participant.channelId!==state.voiceChannelId)return;const entry=ensureVoicePeer(participant,false);try{if(signal.type==='offer'){await entry.connection.setRemoteDescription(signal.description);while(entry.pendingCandidates.length)await entry.connection.addIceCandidate(entry.pendingCandidates.shift());const answer=tuneVoiceDescription(await entry.connection.createAnswer());await entry.connection.setLocalDescription(answer);await Promise.all(entry.connection.getSenders().filter(sender=>sender.track?.kind==='audio').map(prioritizeVoiceSender));await sendVoiceSignal(participant.uid,{type:'answer',description:{type:entry.connection.localDescription.type,sdp:entry.connection.localDescription.sdp}})}else if(signal.type==='answer'){await entry.connection.setRemoteDescription(signal.description);while(entry.pendingCandidates.length)await entry.connection.addIceCandidate(entry.pendingCandidates.shift())}else if(signal.type==='candidate'){if(entry.connection.remoteDescription)await entry.connection.addIceCandidate(signal.candidate);else entry.pendingCandidates.push(signal.candidate)}}catch{}}
  async function applyVoiceState(payload){if(Array.isArray(payload?.channels))state.voiceChannels=payload.channels;if(Array.isArray(payload?.participants))state.voiceParticipants=payload.participants;if(Array.isArray(payload?.iceServers)&&payload.iceServers.length)state.voiceIceServers=payload.iceServers;state.voiceRelayConfigured=payload?.relayConfigured===true;if(state.voiceSessionId&&payload?.joined===false){await leaveVoice({notifyServer:false});showNotice('The voice connection was reset. Join the channel again.');return}if(state.voiceChannelId){const active=state.voiceParticipants.filter(participant=>participant.channelId===state.voiceChannelId&&participant.uid!==state.me?.uid);const activeUids=new Set(active.map(participant=>participant.uid));[...state.voicePeers.keys()].filter(uid=>!activeUids.has(uid)).forEach(closeVoicePeer);active.forEach(participant=>ensureVoicePeer(participant,String(state.me?.uid||'').localeCompare(participant.uid)<0));for(const signal of Array.isArray(payload?.signals)?payload.signals:[])await handleVoiceSignal(signal)}renderVoiceChannels()}
