  function applyActiveHeader(){const channel=activeChannel();const conversation=activeConversation();if(channel){refs.conversationSymbol.setAttribute('href','#icon-hash');refs.channelTitle.textContent=channel.name;refs.channelDescription.textContent=channel.description;refs.welcomeTitle.textContent=`Welcome to #${channel.name.toLowerCase().replace(/\s+/g,'-')}`;refs.welcomeDescription.textContent=`This is the start of the ${channel.name} channel.`;refs.input.placeholder=`Message #${channel.name.toLowerCase().replace(/\s+/g,'-')}`}else if(conversation){refs.conversationSymbol.setAttribute('href','#icon-lock');refs.channelTitle.replaceChildren(roleNameElement(conversation.other));refs.channelDescription.textContent=`Private conversation with ${conversation.other.handle}`;refs.welcomeTitle.textContent=`Message ${conversation.other.displayName}`;refs.welcomeDescription.textContent='Only the two of you can read this conversation.';refs.input.placeholder=`Message ${conversation.other.displayName}`}}
  function mergeMessages(key,incoming){const current=state.messages.get(key)||[];const byId=new Map(current.map(message=>[message.id,message]));incoming.forEach(message=>byId.set(message.id,message));const merged=[...byId.values()].sort((a,b)=>Number(a.createdAtMs||0)-Number(b.createdAtMs||0));state.messages.set(key,merged);return merged}
  function renderAttachment(attachment){if(attachment.image){const box=document.createElement('a');box.className='message-attachment image';box.target='_blank';box.rel='noopener';const loading=document.createElement('span');loading.className='attachment-loading';loading.textContent='Loading image…';box.append(loading);void attachmentUrl(attachment).then(url=>{box.href=url;const image=document.createElement('img');image.alt=attachment.name;image.src=url;image.addEventListener('load',()=>loading.remove(),{once:true});image.addEventListener('error',()=>{loading.textContent='Image unavailable'},{once:true});box.append(image)}).catch(()=>{loading.textContent='Image unavailable'});return box}if(attachment.audio||attachment.video){const box=document.createElement('div');box.className=`message-attachment media ${attachment.audio?'audio':'video'}`;const copy=document.createElement('span');copy.className='message-attachment-media-title';const name=document.createElement('strong');name.textContent=attachment.name;const size=document.createElement('small');size.textContent=formatBytes(attachment.size);copy.append(name,size);const media=document.createElement(attachment.audio?'audio':'video');media.controls=true;media.preload='metadata';if(attachment.video)media.playsInline=true;const loading=document.createElement('span');loading.className='attachment-loading';loading.textContent=`Loading ${attachment.audio?'audio':'video'}…`;box.append(copy,loading,media);void attachmentUrl(attachment).then(url=>{media.src=url;loading.remove()}).catch(()=>{loading.textContent=`${attachment.audio?'Audio':'Video'} unavailable`});return box}const button=document.createElement('button');button.type='button';button.className='message-attachment message-attachment-file';const icon=document.createElementNS('http://www.w3.org/2000/svg','svg');const use=document.createElementNS('http://www.w3.org/2000/svg','use');use.setAttribute('href','#icon-download');icon.append(use);const copy=document.createElement('span');const name=document.createElement('strong');name.textContent=attachment.name;const size=document.createElement('small');size.textContent=formatBytes(attachment.size);copy.append(name,size);button.append(icon,copy);button.addEventListener('click',async()=>{try{button.disabled=true;const url=await attachmentUrl(attachment);const link=document.createElement('a');link.href=url;link.download=attachment.name;document.body.append(link);link.click();link.remove()}catch(error){showNotice(error.message)}finally{button.disabled=false}});return button}
  function renderReactions(message,content){const root=document.createElement('div');root.className='message-reactions';(message.reactions||[]).forEach(reaction=>{const button=document.createElement('button');button.type='button';button.className=`reaction-chip${reaction.self?' self':''}`;button.textContent=reaction.emoji;const count=document.createElement('span');count.textContent=String(reaction.count);button.append(count);button.addEventListener('click',()=>void toggleReaction(message,reaction.emoji));root.append(button)});if(root.childElementCount)content.append(root)}
  function appendMessageText(root,value){const handles=new Map(state.members.map(member=>[String(member.handle||'').toLowerCase(),member]));String(value||'').split(/(@[A-Za-z0-9_.-]+)/g).forEach(part=>{if(!part.startsWith('@')){root.append(document.createTextNode(part));return}const lower=part.toLowerCase();const member=handles.get(lower);if(lower!=='@everyone'&&!member){root.append(document.createTextNode(part));return}const mention=document.createElement('span');mention.className=`message-mention${lower===String(state.me?.handle||'').toLowerCase()?' self':''}${lower==='@everyone'?' everyone':''}`;mention.textContent=part;if(member)mention.addEventListener('click',()=>viewMemberProfile(member));root.append(mention)})}
  function renderMessages(){
    closeMessageContextMenu();
    const key=scopeKey();
    const messages=state.messages.get(key)||[];
    refs.messageList.replaceChildren();
    let previous=null;
    messages.forEach(message=>{
      const grouped=previous&&previous.author?.uid===message.author?.uid&&Number(message.createdAtMs)-Number(previous.createdAtMs)<5*60*1000;
      const article=document.createElement('article');
      article.className=`message role-${String(message.author?.role||'member')}${grouped?' grouped':''}`;
      article.dataset.messageId=message.id;
      article.addEventListener('contextmenu',event=>{event.preventDefault();openMessageContextMenu(event,message)});
      const avatar=avatarElement(message.author);
      const knownMember=state.members.find(member=>member.uid===message.author?.uid);
      if(knownMember){avatar.classList.add('profile-link');avatar.tabIndex=0;avatar.setAttribute('role','button');avatar.addEventListener('click',()=>viewMemberProfile(knownMember));avatar.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();viewMemberProfile(knownMember)}})}
      article.append(avatar);
      const content=document.createElement('div');content.className='message-content';
      const meta=document.createElement('div');meta.className='message-meta';
      const author=document.createElement(knownMember?'button':'span');author.className='message-author';author.append(roleNameElement(message.author));if(knownMember){author.type='button';author.addEventListener('click',()=>viewMemberProfile(knownMember))}meta.append(author);
      if(message.author?.role&&message.author.role!=='member'){const badge=document.createElement('span');badge.className='message-role';badge.textContent=roleLabel(message.author.role);meta.append(badge)}
      if(message.author?.caffeine)meta.append(caffeineBadge());
      const time=document.createElement('time');time.className='message-time';time.dateTime=message.createdAt||'';time.textContent=formatTime(message.createdAtMs);meta.append(time);content.append(meta);
      if(message.text){const text=document.createElement('p');text.className='message-text';appendMessageText(text,message.text);content.append(text)}
      if(message.attachments?.length){const attachments=document.createElement('div');attachments.className='message-attachments';message.attachments.forEach(attachment=>attachments.append(renderAttachment(attachment)));content.append(attachments)}
      renderReactions(message,content);article.append(content);
      if(grouped){const compact=document.createElement('time');compact.className='message-time-compact';compact.textContent=formatTime(message.createdAtMs,true);article.append(compact)}
      const react=svgButton('smile','reaction-add','Add reaction');react.addEventListener('click',event=>{event.stopPropagation();openReactionPicker(article,message)});article.append(react);
      if(message.author?.uid===state.me?.uid||(state.active.type==='channel'&&isModerator())){const remove=svgButton('trash','message-delete','Delete message');remove.addEventListener('click',()=>void deleteMessage(message));article.append(remove)}
      refs.messageList.append(article);previous=message;
    });
    refs.loadOlder.hidden=!state.hasMore.get(key);
  }
  function messageCanDelete(message){return message.author?.uid===state.me?.uid||(state.active.type==='channel'&&isModerator())}
  function closeMessageContextMenu(){state.contextMessage=null;refs.messageContextMenu.hidden=true;refs.messageContextMenu.replaceChildren()}
  async function copyChatText(value,label='Copied.'){const text=String(value||'');try{await navigator.clipboard.writeText(text)}catch{const input=document.createElement('textarea');input.value=text;input.style.position='fixed';input.style.opacity='0';document.body.append(input);input.select();document.execCommand('copy');input.remove()}showNotice(label,'success')}
  function messageContextAction(label,icon,action,{danger=false}={}){const button=document.createElement('button');button.type='button';button.className=`message-context-action${danger?' danger':''}`;button.setAttribute('role','menuitem');const text=document.createElement('span');text.textContent=label;const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');const use=document.createElementNS('http://www.w3.org/2000/svg','use');use.setAttribute('href',`#icon-${icon}`);svg.append(use);button.append(text,svg);button.addEventListener('click',()=>{closeMessageContextMenu();void action()});return button}
  function openMessageContextMenu(event,message){closeMessageContextMenu();document.querySelectorAll('.reaction-picker').forEach(node=>node.remove());state.contextMessage=message;const reactions=document.createElement('div');reactions.className='message-context-reactions';REACTIONS.slice(0,5).forEach(emoji=>{const button=document.createElement('button');button.type='button';button.textContent=emoji;button.setAttribute('aria-label',`React ${emoji}`);button.addEventListener('click',()=>{closeMessageContextMenu();void toggleReaction(message,emoji)});reactions.append(button)});refs.messageContextMenu.append(reactions);const reply=()=>{const handle=String(message.author?.handle||'').trim();refs.input.value=`${handle}${handle?' ':''}${refs.input.value}`;refs.input.focus();refs.input.setSelectionRange(refs.input.value.length,refs.input.value.length);updateComposer()};refs.messageContextMenu.append(messageContextAction('Reply','reply',reply));if(message.text)refs.messageContextMenu.append(messageContextAction('Copy text','copy',()=>copyChatText(message.text,'Message copied.')));refs.messageContextMenu.append(messageContextAction('Copy message ID','copy',()=>copyChatText(message.id,'Message ID copied.')));if(messageCanDelete(message)){const divider=document.createElement('div');divider.className='message-context-divider';refs.messageContextMenu.append(divider,messageContextAction('Delete message','trash',()=>deleteMessage(message),{danger:true}))}refs.messageContextMenu.hidden=false;const rect=refs.messageContextMenu.getBoundingClientRect();const margin=8;const left=Math.max(margin,Math.min(event.clientX,window.innerWidth-rect.width-margin));const top=Math.max(margin,Math.min(event.clientY,window.innerHeight-rect.height-margin));refs.messageContextMenu.style.left=`${left}px`;refs.messageContextMenu.style.top=`${top}px`;refs.messageContextMenu.querySelector('button')?.focus()}
  function openReactionPicker(article,message){document.querySelectorAll('.reaction-picker').forEach(node=>node.remove());const picker=document.createElement('div');picker.className='reaction-picker';REACTIONS.forEach(emoji=>{const button=document.createElement('button');button.type='button';button.textContent=emoji;button.setAttribute('aria-label',`React ${emoji}`);button.addEventListener('click',()=>{picker.remove();void toggleReaction(message,emoji)});picker.append(button)});article.append(picker);const close=event=>{if(!picker.contains(event.target)){picker.remove();document.removeEventListener('pointerdown',close)}};setTimeout(()=>document.addEventListener('pointerdown',close),0)}
  async function toggleReaction(message,emoji){try{const payload=await fetchJson(`${API}/messages/${encodeURIComponent(state.active.id)}/${encodeURIComponent(message.id)}/reactions`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({emoji})});message.reactions=payload.reactions||[];renderMessages()}catch(error){showNotice(error.message)}}
  function markRead(){const key=scopeKey();const messages=state.messages.get(key)||[];const activity=state.active.type==='channel'?Number(state.latestActivity[state.active.id]||0):Number(activeConversation()?.lastMessageAtMs||0);state.lastRead[key]=Math.max(activity,...messages.map(message=>Number(message.createdAtMs||0)),Date.now());saveLastRead();renderChannels();renderDirects()}
  async function loadMessages({initial=false,older=false,poll=false,replace=false}={}){if(!state.me)return;const scope={...state.active};const key=scopeKey(scope);const current=state.messages.get(key)||[];let query=scope.type==='channel'?`?channel=${encodeURIComponent(scope.id)}`:`?conversation=${encodeURIComponent(scope.id)}`;if(older&&current.length)query+=`&before=${Math.max(1,Number(current[0].createdAtMs||0))}`;else if(poll&&!replace){const newest=current.length?Number(current[current.length-1].createdAtMs||0):1;query+=`&after=${Math.max(1,newest-1)}`}const wasNearBottom=refs.scroller.scrollHeight-refs.scroller.scrollTop-refs.scroller.clientHeight<100;const beforeHeight=refs.scroller.scrollHeight;const payload=await fetchJson(`${API}/messages${query}`,{cache:'no-store'});if(key!==scopeKey())return;if(replace)state.messages.set(key,[]);mergeMessages(key,payload.messages||[]);if(!poll||replace)state.hasMore.set(key,payload.hasMore===true);state.loaded.add(key);renderMessages();if(older)refs.scroller.scrollTop=Math.max(0,refs.scroller.scrollHeight-beforeHeight);else if(initial||wasNearBottom)requestAnimationFrame(()=>{refs.scroller.scrollTop=refs.scroller.scrollHeight});const newest=(state.messages.get(key)||[]).at(-1);if(newest&&scope.type==='channel')state.latestActivity[scope.id]=Math.max(Number(state.latestActivity[scope.id]||0),Number(newest.createdAtMs||0));if(!document.hidden)markRead();setConnection('Live','connected')}
  async function switchScope(scope){if(scope.type==='channel'&&!state.channels.some(item=>item.id===scope.id))return;if(scope.type==='dm'&&!state.conversations.some(item=>item.id===scope.id))return;if(scopeKey(scope)===scopeKey()){closeDrawers();return}state.active={...scope};state.files=[];renderFilePreviews();applyActiveHeader();renderChannels();renderDirects();renderMessages();closeDrawers();const key=scopeKey();if(!state.loaded.has(key)){setConnection('Loading');try{await loadMessages({initial:true})}catch(error){setConnection('Offline','error');showNotice(error.message)}}else{markRead();requestAnimationFrame(()=>{refs.scroller.scrollTop=refs.scroller.scrollHeight})}}

  function fileMime(file){const supplied=String(file.type||'').toLowerCase();if(ALLOWED_MIME.has(supplied))return supplied;return String(MIME_BY_EXTENSION[String(file.name||'').split('.').pop()?.toLowerCase()]||'').toLowerCase()}
  function chooseFiles(fileList){const candidates=[...fileList];const next=[...state.files];for(const file of candidates){const mime=fileMime(file);if(next.length>=MAX_ATTACHMENTS){showNotice(`You can attach up to ${MAX_ATTACHMENTS} files.`);break}if(!ALLOWED_MIME.has(mime)){showNotice(`${file.name} is not a supported attachment type.`);continue}if(file.size<1||file.size>MAX_FILE_SIZE){showNotice(`${file.name} must be 8 MB or smaller.`);continue}if(next.reduce((total,item)=>total+item.file.size,0)+file.size>MAX_MESSAGE_ATTACHMENTS){showNotice('Attachments can total up to 8 MB per message.');continue}next.push({file,mime,status:''})}state.files=next;refs.attachmentInput.value='';renderFilePreviews();updateComposer()}
  function renderFilePreviews(){refs.attachmentPreviews.replaceChildren();state.files.forEach((item,index)=>{const root=document.createElement('div');root.className='attachment-preview';const icon=document.createElementNS('http://www.w3.org/2000/svg','svg');const use=document.createElementNS('http://www.w3.org/2000/svg','use');use.setAttribute('href','#icon-paperclip');icon.append(use);const copy=document.createElement('span');const name=document.createElement('strong');name.textContent=item.file.name;const size=document.createElement('small');size.textContent=item.status||formatBytes(item.file.size);copy.append(name,size);const remove=svgButton('close','','Remove attachment');remove.addEventListener('click',()=>{if(state.busy)return;state.files.splice(index,1);renderFilePreviews();updateComposer()});root.append(icon,copy,remove);refs.attachmentPreviews.append(root)});refs.attachmentPreviews.hidden=!state.files.length}
  function readFileBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error(`Could not read ${file.name}.`));reader.onload=()=>resolve(String(reader.result||'').split(',')[1]||'');reader.readAsDataURL(file)})}
  async function uploadAttachment(item,fileIndex){if(item.id)return item.id;item.status='Preparing…';renderFilePreviews();const uploadId=item.uploadId||(crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`).replace(/[^A-Za-z0-9_-]/g,'');item.uploadId=uploadId;const encoded=await readFileBase64(item.file);const chunks=[];for(let offset=0;offset<encoded.length;offset+=CHUNK_LENGTH)chunks.push(encoded.slice(offset,offset+CHUNK_LENGTH));let attachmentId='';for(let index=0;index<chunks.length;index++){item.status=`Uploading ${Math.round(index/chunks.length*100)}%`;renderFilePreviews();const payload=await fetchJson(`${API}/attachments/${encodeURIComponent(uploadId)}/${index}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({totalChunks:chunks.length,mime:item.mime,name:item.file.name,size:item.file.size,chunk:chunks[index]})});attachmentId=payload.id||attachmentId}item.status='Finishing…';renderFilePreviews();const completed=await fetchJson(`${API}/attachments/${encodeURIComponent(uploadId)}/complete`,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});item.id=completed.attachment?.id||attachmentId;if(!item.id)throw new Error(`Could not finish ${item.file.name}.`);item.status=`Ready ${fileIndex+1}/${state.files.length}`;renderFilePreviews();return item.id}
  function commandVisible(command){if(command.network)return ['owner','co_owner','admin'].includes(state.me?.role);if(command.manager)return state.me?.canManageChannels===true;if(command.staff)return isModerator();return true}
  function findSlashCommand(name){const value=String(name||'').toLowerCase();return SLASH_COMMANDS.find(command=>command.name===value||(command.aliases||[]).includes(value))}
  function resolveCommandMember(value){const query=String(value||'').trim().split(/\s+/)[0].toLowerCase();if(!query)return null;return state.members.find(member=>String(member.handle||'').toLowerCase()===query||String(member.handle||'').slice(1).toLowerCase()===query.replace(/^@/,'')||String(member.displayName||'').toLowerCase()===query.replace(/^@/,''))||null}
  function renderCommandHelp(){refs.commandList.replaceChildren();SLASH_COMMANDS.filter(commandVisible).forEach(command=>{const item=document.createElement('div');item.className='command-list-item';const usage=document.createElement('code');usage.textContent=command.usage;const description=document.createElement('span');description.textContent=command.description;item.append(usage,description);refs.commandList.append(item)});refs.commandDialog.showModal()}
  async function commandOpenDm(member){const payload=await fetchJson(`${API}/conversations`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({participantUid:member.uid})});const conversation=payload.conversation;if(!conversation)throw new Error('The private conversation could not be opened.');mergeConversations([conversation,...state.conversations.filter(item=>item.id!==conversation.id)]);await switchScope({type:'dm',id:conversation.id})}
  async function commandAccountAction(member,action,label,reason=''){if(!isModerator())throw new Error('You do not have permission to use that command.');if(member.self)throw new Error('You cannot use that command on yourself.');if(!confirm(`${label} ${member.displayName}?`))return;await fetchJson(`/api/owner-dashboard/users/${encodeURIComponent(member.uid)}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,reason:String(reason||'').slice(0,180)})});showNotice(`${member.displayName}: ${label.toLowerCase()} completed.`,'success')}
  async function commandChatMute(member,action){if(!isModerator())throw new Error('You do not have permission to use that command.');if(member.self)throw new Error('You cannot mute yourself.');const body={action,targetUid:member.uid};if(action==='mute'){const duration=prompt(`How long should ${member.displayName} be muted?\nUse 10m, 2h, 1d, or 1w.`,'10m');if(duration===null)return;const reason=prompt(`Why are you muting ${member.displayName}?`,'');if(reason===null)return;body.duration=duration.trim();body.reason=reason.trim();if(!body.duration)throw new Error('Enter how long the mute should last.');if(!body.reason)throw new Error('A reason is required.')}const payload=await fetchJson(`${API}/moderation/mutes`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(payload.muted){const until=new Date(payload.mute?.expiresAtMs||0).toLocaleString();showNotice(`${member.displayName} is muted until ${until}.`,'success')}else showNotice(`${member.displayName} can send messages again.`,'success')}
  async function commandChannelAccess(minimumRole){const channel=activeChannel();if(!channel)throw new Error('Use this command inside a text channel.');if(!state.me?.canManageChannels)throw new Error('You do not have permission to manage channels.');const payload=await fetchJson(`${API}/channels`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'update',kind:'text',id:channel.id,name:channel.name,description:channel.description||'',minimumRole})});applyChannelConfiguration(payload);showNotice(minimumRole==='member'?'Channel unlocked.':'Channel locked to moderators and above.','success')}
  async function executeSlashCommand(raw){const match=String(raw||'').match(/^\/([A-Za-z]+)(?:\s+([\s\S]*))?$/);if(!match)throw new Error('That command is not valid. Type /help to see Nyx commands.');const command=findSlashCommand(match[1]);if(!command)throw new Error(`Unknown command /${match[1]}. Type /help to see Nyx commands.`);const args=String(match[2]||'').trim();if(command.name==='help'){renderCommandHelp();return {handled:true}}if(command.name==='shrug')return {text:`${args}${args?' ':''}¯\\_(ツ)_/¯`};if(command.name==='tableflip')return {text:`${args}${args?' ':''}(╯°□°）╯︵ ┻━┻`};if(command.name==='unflip')return {text:`${args}${args?' ':''}┬─┬ ノ( ゜-゜ノ)`};if(command.name==='me'){if(!args)throw new Error('Add an action after /me.');return {text:`* ${state.me?.displayName||'Nyx member'} ${args}`}}if(command.name==='who'){const online=state.members.filter(member=>member.online);showNotice(online.length?`Online: ${online.map(member=>member.displayName).join(', ')}`:'No other members are online.','success');return {handled:true}}if(command.name==='ping'){const started=performance.now();await fetchJson(`${API}/conversations`,{cache:'no-store'});showNotice(`Nyx Chat API: ${Math.max(1,Math.round(performance.now()-started))} ms.`,'success');return {handled:true}}if(command.name==='dm'){const member=resolveCommandMember(args);if(!member||member.self)throw new Error('Choose another member, for example /dm @person.');const rest=args.split(/\s+/).slice(1).join(' ');await commandOpenDm(member);return {handled:true,input:rest}}if(command.name==='giftcaffeine'){const member=resolveCommandMember(args);if(!member||member.self)throw new Error('Choose another member, for example /giftcaffeine @person.');const payload=await fetchJson(`${API}/caffeine/gifts`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({recipientUid:member.uid})});state.caffeine=payload.caffeine||state.caffeine;renderCaffeine();showNotice(`Caffeine gift sent to ${member.displayName}.`,'success');return {handled:true}}if(['ban','ipban','unban'].includes(command.name)){const member=resolveCommandMember(args);if(!member)throw new Error(`Choose a member, for example /${command.name} @person.`);const action=command.name==='ban'?'disable':command.name==='ipban'?'disable_with_ip_ban':'enable';const reason=args.split(/\s+/).slice(1).join(' ');await commandAccountAction(member,action,command.name==='ban'?'Disable account':command.name==='ipban'?'Disable account and block recorded IP':'Re-enable account',reason);return {handled:true}}if(command.name==='mute'||command.name==='unmute'){const member=resolveCommandMember(args);if(!member)throw new Error(`Choose a member, for example /${command.name} @person.`);await commandChatMute(member,command.name);return {handled:true}}if(command.name==='lock'||command.name==='unlock'){await commandChannelAccess(command.name==='lock'?'moderator':'member');return {handled:true}}if(command.name==='join'){const query=args.toLowerCase().replace(/^#/,'');const channel=state.voiceChannels.find(item=>item.id===query||item.name.toLowerCase()===query);if(!channel)throw new Error('Choose a voice channel, for example /join Lounge.');await joinVoice(channel.id);return {handled:true}}if(command.name==='disconnect'){await leaveVoice();return {handled:true}}if(command.name==='micmute'||command.name==='micunmute'){if(!state.voiceStream)throw new Error('Join a voice channel first.');if((command.name==='micmute')!==state.voiceMuted)toggleVoiceMute();return {handled:true}}if(command.name==='deafen'||command.name==='undeafen'){if(!state.voiceChannelId)throw new Error('Join a voice channel first.');if((command.name==='deafen')!==state.voiceDeafened)toggleVoiceDeafen();return {handled:true}}throw new Error('That command is not available in Nyx Chat.')}
  async function sendMessage(event){event.preventDefault();if(state.busy)return;let text=refs.input.value.trim();if(!text&&!state.files.length)return;state.busy=true;updateComposer();refs.attachmentButton.disabled=true;try{if(text.startsWith('/')){const result=await executeSlashCommand(text);if(result?.handled){refs.input.value=String(result.input||'');closeMentionMenu();updateComposer();return}text=String(result?.text||'').trim()}const attachmentIds=[];for(let index=0;index<state.files.length;index++)attachmentIds.push(await uploadAttachment(state.files[index],index));const requestId=(crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`).replace(/[^A-Za-z0-9_-]/g,'');const body={text,requestId,attachmentIds};if(state.active.type==='channel')body.channel=state.active.id;else body.conversationId=state.active.id;const payload=await fetchJson(`${API}/messages`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const key=scopeKey();refs.input.value='';state.files=[];renderFilePreviews();updateComposer();mergeMessages(key,[payload.message]);if(state.active.type==='channel')state.latestActivity[state.active.id]=Number(payload.message?.createdAtMs||Date.now());else{const conversation=activeConversation();if(conversation){conversation.lastMessageAtMs=Number(payload.message?.createdAtMs||Date.now());conversation.lastMessageText=payload.message?.text||`Attached ${payload.message?.attachments?.length||1} file`;conversation.updatedAtMs=conversation.lastMessageAtMs;state.conversations.sort((a,b)=>b.updatedAtMs-a.updatedAtMs);renderDirects()}}renderMessages();markRead();requestAnimationFrame(()=>{refs.scroller.scrollTop=refs.scroller.scrollHeight})}catch(error){showNotice(error.message)}finally{state.busy=false;refs.attachmentButton.disabled=false;updateComposer();refs.input.focus()}}
